// This code has been fully generated by an AI.

// Package routesvg turns a stored track into a small SVG path for activity
// tiles. The route is drawn without map tiles, so lists stay fast, work
// offline and do not use any map provider quota.
package routesvg

import (
	"math"
	"strconv"
	"strings"

	"github.com/paulmach/orb"
	"github.com/paulmach/orb/simplify"

	"github.com/stefanluchs/my-velo/internal/geo"
)

// Size of the SVG viewBox used by the tiles (width × height).
const (
	Width  = 320
	Height = 120
	// pad keeps the stroke and the start/end dots inside the viewBox.
	pad = 8
)

// Route is a route projected into the viewBox.
type Route struct {
	// D is the SVG path data, e.g. "M8.0,60.0L20.5,58.1…".
	D string
	// Start and end point in viewBox coordinates.
	StartX, StartY, EndX, EndY float64
}

// FromPolyline projects an encoded polyline (see geo.EncodePolyline) with
// Web Mercator, fits it centred into the viewBox keeping the aspect ratio
// and drops detail a tile cannot show. ok is false for invalid or
// degenerate tracks (fewer than two distinct points).
func FromPolyline(polyline string) (r Route, ok bool) {
	ls, err := geo.DecodePolyline(polyline)
	if err != nil || len(ls) < 2 {
		return Route{}, false
	}
	pts := make(orb.LineString, len(ls))
	for i, p := range ls {
		pts[i] = mercator(p)
	}
	b := pts.Bound()
	spanX, spanY := b.Max[0]-b.Min[0], b.Max[1]-b.Min[1]
	var scale float64
	switch {
	case spanX == 0 && spanY == 0:
		return Route{}, false
	case spanX == 0:
		scale = (Height - 2*pad) / spanY
	case spanY == 0:
		scale = (Width - 2*pad) / spanX
	default:
		scale = math.Min((Width-2*pad)/spanX, (Height-2*pad)/spanY)
	}
	offX := (Width - spanX*scale) / 2
	offY := (Height - spanY*scale) / 2
	for i, p := range pts {
		// SVG y grows downwards, Mercator y northwards.
		pts[i] = orb.Point{offX + (p[0]-b.Min[0])*scale, offY + (b.Max[1]-p[1])*scale}
	}
	if len(pts) > 2 {
		// Half a viewBox unit is below what a tile can show.
		pts = simplify.DouglasPeucker(0.5).LineString(pts)
	}

	var sb strings.Builder
	sb.Grow(len(pts) * 12)
	for i, p := range pts {
		if i == 0 {
			sb.WriteByte('M')
		} else {
			sb.WriteByte('L')
		}
		sb.WriteString(strconv.FormatFloat(p[0], 'f', 1, 64))
		sb.WriteByte(',')
		sb.WriteString(strconv.FormatFloat(p[1], 'f', 1, 64))
	}
	first, last := pts[0], pts[len(pts)-1]
	return Route{D: sb.String(), StartX: round1(first[0]), StartY: round1(first[1]), EndX: round1(last[0]), EndY: round1(last[1])}, true
}

// mercator projects lon/lat degrees to Web Mercator (radian units).
func mercator(p orb.Point) orb.Point {
	lat := math.Max(-85, math.Min(85, p[1])) * math.Pi / 180
	return orb.Point{p[0] * math.Pi / 180, math.Log(math.Tan(math.Pi/4 + lat/2))}
}

func round1(v float64) float64 { return math.Round(v*10) / 10 }
